/**
 * The other inspector — an ambient figure who walks the same loop the
 * player audits. He is BASELINE, not an anomaly: identical every loop,
 * always mid-corridor at spawn, always walking south then back. His
 * constancy is the point — it makes "the walker" a learnable part of
 * normal so any future behavior change reads as a divergence.
 */
import { CreateBox } from "@babylonjs/core/Meshes/Builders/boxBuilder";
import { CreatePlane } from "@babylonjs/core/Meshes/Builders/planeBuilder";
import type { TransformNode } from "@babylonjs/core/Meshes/transformNode";
import { StandardMaterial } from "@babylonjs/core/Materials/standardMaterial";
import { DynamicTexture } from "@babylonjs/core/Materials/Textures/dynamicTexture";
import { Color3 } from "@babylonjs/core/Maths/math.color";
import { Vector3 } from "@babylonjs/core/Maths/math.vector";
import type { Scene } from "@babylonjs/core/scene";
import { buildFigure, type Figure } from "../figures";
import type { MaterialSet } from "../materials/library";
import type { WorldRegistry } from "../registry";

const WALK_Z0 = 7;
const WALK_Z1 = 48;
const LANE_X = 0.55; // his lane — right-of-centre, drilled into you every loop
const SPEED = 1.05;
const PAUSE_S = 5;
const HOME_Z = 16; // loop-rebaseline spot — always mid-corridor on loop 1

export type WalkerMode =
  | "normal"
  | "backwards"
  | "stare"
  | "absent"
  | "crawl"
  | "fast"
  | "charge"
  | "midstep"
  | "offlane"
  | "notes"
  | "follow";

export interface AmbientWalker {
  update(dt: number, playerPos?: Vector3): void;
  /** the figure root — anomalies read his position/gait from it */
  root: TransformNode;
  /** figure pivots for anomaly posing */
  fig: Figure;
  /** baseline courtesy (he never does it): while armed, crossing z≈gz
   *  turns his head toward the bench for ~1.1s. null disarms. */
  setGreetAt(gz: number | null): void;
  reset(): void;
  /** anomaly hook — 'backwards' flips facing vs travel, 'stare' halts
   *  mid-corridor facing the player's approach. reset() restores normal. */
  setMode(mode: WalkerMode): void;
  /** 'charge' mode only — the driving anomaly feeds the player's z each
   *  frame; he sprints to within a step of it and holds there. */
  chargeAt(playerZ: number): void;
  /** move his hold point to z and freeze him there facing north —
   *  walker.wait stations him at the south mouth this way. */
  holdAt(z: number): void;
  /** wired by the app to audio — fires on each stride landing while
   *  he is actually walking. Not anomalous footsteps: his cadence is
   *  baseline, so a changed cadence stays anomalous. */
  onStep?: (pos: Vector3) => void;
}

export function buildAmbientWalker(
  scene: Scene,
  root: TransformNode,
  _mats: MaterialSet,
  registry: WorldRegistry,
): AmbientWalker {
  // shared humanoid: shoes, trouser legs, tapered coat, collar + lapels,
  // hi-vis band, hands, sphere skull + hair + drawn face. Hip/arm pivots
  // keep the ".hip." / ".arm." names walker.crowd's clone filters for.
  const fig = buildFigure(scene, root, "ambient.walker", { kind: "inspector" });
  const g = fig.root;
  registry.register("ambient.walker", g);
  const legPivots = fig.hips;
  const armPivots = fig.arms;

  // the case file he carries — a real clipboard: dark board, clip band,
  // a typed audit sheet with a red finding mark
  const clipMat = new StandardMaterial("ambient.walker.clip", scene);
  clipMat.diffuseColor = new Color3(0.16, 0.13, 0.1);
  clipMat.specularColor = new Color3(0.03, 0.03, 0.03);
  const clip = CreateBox("ambient.walker.clip", { width: 0.2, height: 0.28, depth: 0.018 }, scene);
  clip.material = clipMat;
  clip.position = new Vector3(0.02, -0.68, 0.1);
  clip.parent = armPivots[0]!;
  const clipTex = new DynamicTexture("ambient.walker.clip.tex", { width: 128, height: 180 }, scene, true);
  const cc = clipTex.getContext() as unknown as CanvasRenderingContext2D;
  cc.fillStyle = "#e8e3d4";
  cc.fillRect(8, 10, 112, 166); // sheet
  cc.fillStyle = "#8f8c82"; // metal clip band
  cc.fillRect(8, 10, 112, 16);
  cc.fillStyle = "#3c382f";
  cc.fillRect(52, 6, 24, 10); // clip tab
  cc.strokeStyle = "#4c463b";
  cc.lineWidth = 2;
  for (let i = 0; i < 9; i++) {
    const y = 40 + i * 14;
    cc.beginPath();
    cc.moveTo(16, y);
    cc.lineTo(16 + 84 - (i % 3) * 16, y);
    cc.stroke();
  }
  cc.strokeStyle = "#8c2f24";
  cc.lineWidth = 4;
  cc.strokeRect(78, 132, 34, 30); // red finding box
  cc.beginPath();
  cc.moveTo(84, 148);
  cc.lineTo(92, 156);
  cc.lineTo(106, 136);
  cc.stroke(); // check mark
  clipTex.update();
  const clipFaceMat = new StandardMaterial("ambient.walker.clip.face", scene);
  clipFaceMat.diffuseTexture = clipTex;
  clipFaceMat.specularColor = new Color3(0.03, 0.03, 0.03);
  const clipFace = CreatePlane("ambient.walker.clip.page", { width: 0.19, height: 0.27 }, scene);
  clipFace.material = clipFaceMat;
  clipFace.position = new Vector3(0.02, -0.68, 0.111);
  clipFace.parent = armPivots[0]!;

  let z = HOME_Z;
  let dir = 1; // walking south (+z) at loop start
  let pauseT = 0;
  let inspectT = 0; // clipboard-read beat during the north-end pause
  let boardT = 0; // departure-board read beat during the south-end pause
  let watchT = 0; // mid-route watch-check beat (every other pass)
  let watchArm = -1; // which direction the armed watch check fires on
  let resets = 0; // parity driving the alternating watch check
  let nodT = 0; // the small head dip he gives when he halts for you
  let greetZ: number | null = null; // courtesy hook — see setGreetAt
  let greetT = 0;
  let greeted = false;
  let blockedT = 0;
  let bobT = 0;
  let lastStepPh = 0;
  let mode: WalkerMode = "normal";
  let chargeZ: number | null = null;
  let lastPz: number | undefined;
  let followSide = -2.7;
  const stepIfLanded = (stepping: boolean) => {
    const ph = Math.floor((bobT * 3.4) / Math.PI);
    if (ph !== lastStepPh) {
      lastStepPh = ph;
      if (stepping) api.onStep?.(g.position);
    }
  };

  const api: AmbientWalker = {
    reset() {
      mode = "normal";
      chargeZ = null;
      z = HOME_Z;
      dir = 1;
      pauseT = 0;
      inspectT = 0;
      boardT = 0;
      watchT = 0;
      resets += 1;
      watchArm = resets % 2 === 0 ? -1 : 1; // he checks the time on alternating passes
      nodT = 0;
      blockedT = 0;
      fig.headPivot.rotation.x = 0;
      g.setEnabled(true);
      g.position.set(LANE_X, 0, z);
      g.rotation.set(0, dir > 0 ? 0 : Math.PI, 0);
    },
    chargeAt(playerZ: number) {
      chargeZ = playerZ;
    },
    root: g,
    fig,
    setGreetAt(gz: number | null) {
      greetZ = gz;
      greeted = false;
      greetT = 0;
    },
    holdAt(zHold: number) {
      z = zHold;
      mode = "stare";
      pauseT = 0;
      g.setEnabled(true);
      g.rotation.y = Math.PI;
      g.position.set(LANE_X, 0, z);
    },
    setMode(m: WalkerMode) {
      mode = m;
      g.rotation.x = 0; // charge's sprint lean never leaks into other modes
      if (m === "absent") {
        // he is simply not there this loop — the routine has a hole in it
        g.setEnabled(false);
        return;
      }
      g.setEnabled(true);
      if (m === "stare") {
        // stops where he is, squared up to face the player's approach
        pauseT = 0;
        g.rotation.y = Math.PI;
      }
    },
    update(dt, playerPos) {
      // crawl: route and cadence intact but nearly stationary — he
      // covers a fifth of the route with a slowed, heavy stride
      // fast: same route at nearly double pace — he breezes the loop
      // you know he takes a minute on, and the cadence reads urgent
      if (greetZ !== null && !greeted && Math.abs(z - greetZ) < 1.4) {
        greetT = 1.1;
        greeted = true;
      }
      if (greetZ !== null && Math.abs(z - greetZ) > 2.6) greeted = false;
      if (greetT > 0) greetT -= dt;
      const pace = mode === "crawl" ? 0.18 : mode === "fast" ? 1.9 : 1;
      bobT += dt * (mode === "crawl" ? 0.35 : mode === "fast" ? 1.7 : 1);
      if (mode === "absent") return;
      const lane = mode === "offlane" ? -LANE_X : LANE_X;
      if (mode === "stare") {
        // dead still except the slightest drift of the head
        g.position.set(lane, 0, z);
        for (const p of [...legPivots, ...armPivots]) p.rotation.x = 0;
        fig.headPivot.rotation.x = 0;
        return;
      }
      if (mode === "notes") {
        // writing you up: stopped where he stood, clipboard arm raised
        // to his chest, head bent over the page, pen arm working
        g.position.set(lane, 0, z);
        for (const p of legPivots) p.rotation.x = 0;
        armPivots[0]!.rotation.x = -1.05; // clipboard up
        armPivots[1]!.rotation.x = -0.9 + Math.sin(bobT * 7) * 0.06; // pen scribbles
        fig.headPivot.rotation.x = 0.55; // eyes on the page
        fig.headPivot.rotation.y = 0;
        return;
      }
      if (mode === "midstep") {
        // frozen mid-stride — legs split, arms mid-swing, facing his
        // direction of travel; reads normal at a glance and wrong the
        // moment you watch for the next step that never lands
        g.rotation.y = dir > 0 ? 0 : Math.PI;
        g.position.set(lane, 0, z);
        legPivots[0]!.rotation.x = 0.46;
        legPivots[1]!.rotation.x = -0.46;
        armPivots[0]!.rotation.x = -0.3;
        armPivots[1]!.rotation.x = 0.3;
        fig.headPivot.rotation.x = 0;
        return;
      }
      if (mode === "charge") {
        // the man you know runs at you — sprint along his lane until a
        // step behind the player, then hold there at your shoulder.
        // Driven per-frame by the anomaly through chargeAt().
        if (chargeZ === null) {
          g.position.set(lane, 0, z);
          return;
        }
        const dz = chargeZ - z;
        const closing = Math.abs(dz) > 1.15;
        if (closing) {
          z += Math.sign(dz) * 3.4 * dt;
          bobT += dt * 2.6;
          g.rotation.y = dz > 0 ? 0 : Math.PI;
        }
        g.rotation.x = closing ? 0.09 : 0; // a sprint leans, a hold squares up
        const bob = closing ? Math.abs(Math.sin(bobT * 3.4)) * 0.04 : 0;
        g.position.set(lane, bob, z);
        const swing = closing ? Math.sin(bobT * 3.4) : 0;
        legPivots[0]!.rotation.x = swing * 0.62;
        legPivots[1]!.rotation.x = -swing * 0.62;
        armPivots[0]!.rotation.x = -swing * 0.4;
        armPivots[1]!.rotation.x = swing * 0.4;
        stepIfLanded(closing);
        return;
      }
      if (mode === "follow" && playerPos) {
        // he falls in behind you — holds ~2.7 m off whichever end you're
        // walking away from, matching your pace; when you stand still he
        // just stands there. Turn around: mid-stride or already waiting.
        if (lastPz === undefined || playerPos.z !== lastPz)
          followSide = lastPz !== undefined && playerPos.z < lastPz ? 2.7 : -2.7;
        const behind = followSide;
        lastPz = playerPos.z;
        const target = Math.min(Math.max(playerPos.z + behind, 3), 52);
        const dz = target - z;
        const closing = Math.abs(dz) > 0.04;
        if (closing) {
          z += Math.sign(dz) * Math.min(Math.abs(dz), 1.55 * dt * (Math.abs(dz) > 1 ? 1.8 : 1));
          bobT += dt * 1.7;
          g.rotation.y = dz > 0 ? 0 : Math.PI;
        }
        const bob = closing ? Math.abs(Math.sin(bobT * 3.4)) * 0.04 : 0;
        g.position.set(lane, bob, z);
        const swing = closing ? Math.sin(bobT * 3.4) : 0;
        legPivots[0]!.rotation.x = swing * 0.55;
        legPivots[1]!.rotation.x = -swing * 0.55;
        armPivots[0]!.rotation.x = -swing * 0.35;
        armPivots[1]!.rotation.x = swing * 0.35;
        fig.headPivot.rotation.x = 0;
        stepIfLanded(closing);
        return;
      }
      if (pauseT > 0) {
        pauseT -= dt;
        if (inspectT > 0) inspectT -= dt;
        if (boardT > 0) boardT -= dt;
        if (watchT > 0) watchT -= dt;
        if (nodT > 0) nodT -= dt;
      } else {
        // he gives way: if the player is planted on his lane ahead, he
        // halts and waits rather than walking through them. Baseline
        // behavior only — scripted modes are exempt (a frozen
        // 'crawl'/'fast' would mute the anomaly's own signal).
        const blocked =
          mode === "normal" &&
          playerPos != null &&
          Math.abs(playerPos.x - lane) < 0.85 &&
          dir * (playerPos.z - z) > 0.25 &&
          dir * (playerPos.z - z) < 1.15;
        if (blocked) {
          blockedT += dt;
          // acknowledge you with a small nod once he's been held a beat —
          // learned baseline: he gives way politely every loop, so the
          // anomalies that DON'T are louder.
          if (blockedT > 0.7 && nodT <= -1.2) nodT = 0.9;
          if (nodT > 0) nodT -= dt;
          for (const p of [...legPivots, ...armPivots]) p.rotation.x *= 0.85;
          const dip = nodT > 0 ? Math.sin(Math.PI * Math.min(1, (0.9 - nodT) / 0.9)) * 0.22 : 0;
          fig.headPivot.rotation.x = fig.headPivot.rotation.x * 0.85 + dip;
          g.rotation.y = dir > 0 ? 0 : Math.PI;
          g.position.set(lane, 0, z);
          return;
        }
        blockedT = 0;
        nodT = Math.max(0, nodT - dt);
        z += dir * SPEED * dt * pace;
        // mid-route watch check — every other pass he halts a step
        // under the colonnade to check the time. Alternation keeps it a
        // habit, not a metronome; anomalies that take his schedule get
        // read against this.
        if (mode === "normal" && watchT <= 0 && dir === watchArm && Math.abs(z - 33) < 0.35) {
          pauseT = 2.2;
          watchT = 2.2;
          watchArm = 0; // spent for this pass — reset re-arms the other
        }
        if (z >= WALK_Z1 && dir > 0) {
          z = WALK_Z1;
          dir = -1;
          pauseT = PAUSE_S;
          // the south-end beat: he stops under his exit and reads the
          // departure board up the corridor (z40 hangs high on the
          // centreline) — head up, still. Same beat every pass.
          boardT = PAUSE_S * 0.7;
        } else if (z <= WALK_Z0 && dir < 0) {
          z = WALK_Z0;
          dir = 1;
          pauseT = PAUSE_S;
          // the north-end pause is where he does the job: turns to the
          // records bank (west wall, -x), clipboard up, head down.
          // Deterministic — every loop, same end, same read — so it
          // stays baseline.
          inspectT = PAUSE_S * 0.78;
          g.rotation.y = -Math.PI / 2;
        }
        // facing follows mode: normally the direction of travel;
        // 'backwards' keeps him squared away from it (the moonwalk)
        const facing = mode === "backwards" ? -dir : dir;
        g.rotation.y = facing > 0 ? 0 : Math.PI;
      }
      // stride bob — tiny, readable at distance
      const bob = Math.abs(Math.sin(bobT * 3.4)) * 0.028;
      g.position.set(lane, bob, z);
      // limbs swing only while he's actually in stride
      const stepping = pauseT <= 0; // stare/absent returned above
      const swing = stepping ? Math.sin(bobT * 3.4) : 0;
      legPivots[0]!.rotation.x = swing * 0.5;
      legPivots[1]!.rotation.x = -swing * 0.5;
      armPivots[0]!.rotation.x = -swing * 0.32;
      armPivots[1]!.rotation.x = swing * 0.32;
      // the read: clipboard arm rises toward the face, head bows over
      // it — eases in over the pause's first beat, settles out at the
      // end. Overrides the swing-zeroed arm while inspectT lasts.
      if (inspectT > 0) {
        const rise = Math.min(1, Math.max(0, PAUSE_S - pauseT - 0.15) * 3.2);
        const settle = Math.min(1, inspectT * 2.4);
        const lift = Math.min(rise, settle);
        armPivots[0]!.rotation.x = -1.05 * lift;
        fig.headPivot.rotation.x = 0.34 * lift;
      } else if (boardT > 0) {
        // reading the board: head tips up toward the ceiling-hung rows,
        // a hint of lean on the trailing leg. Eases like the inspect.
        const lift = Math.min(
          Math.min(1, Math.max(0, PAUSE_S - pauseT - 0.15) * 3.2),
          Math.min(1, boardT * 2.4),
        );
        fig.headPivot.rotation.x = -0.3 * lift;
        fig.headPivot.rotation.y = -0.12 * lift; // board rides his left
      } else if (watchT > 0) {
        // the time check: left wrist up, eyes down — a shorter beat with
        // a quicker ease so it reads as reflex, not ceremony.
        const lift = Math.min(Math.min(1, Math.max(0, 2.2 - watchT - 0.1) * 4.5), Math.min(1, watchT * 3.0));
        armPivots[0]!.rotation.x = -0.8 * lift;
        armPivots[0]!.rotation.z = 0.35 * lift;
        fig.headPivot.rotation.x = 0.42 * lift;
      } else if (greetT > 0) {
        // the courtesy he never pays: a slow turn toward the bench as he
        // passes. Sits inside the neutral branch — anomalies only ever
        // arm it; baseline z never triggers it.
        const lift = Math.min(1, (1.1 - greetT) * 3.5) * Math.min(1, greetT * 2.5);
        fig.headPivot.rotation.x = 0.05 * lift;
        fig.headPivot.rotation.y = -0.55 * lift; // bench rides his right
      } else {
        fig.headPivot.rotation.x = 0;
        fig.headPivot.rotation.y = 0;
        armPivots[0]!.rotation.z = 0;
      }
      stepIfLanded(stepping);
    },
  };
  return api;
}
